<template>
  <div class="roster-page" :style="{'--roster-cell-height':cellHeight+'px'}">
    <section class="roster-panel">
      <header class="roster-header"><div><div class="eyebrow">人事专区 · 钉钉考勤</div><h2>员工考勤 <el-tag type="info" size="small">钉钉同步</el-tag></h2><p>排班与请假在钉钉维护；此处查看计划班次、实际打卡和个人存假。</p></div><div class="header-actions"><small>{{ week.sync?.latest?.created_at ? '最近同步：'+week.sync.latest.created_at : '尚未同步' }}</small><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" :loading="saving" :disabled="loading || week.sync?.running" @click="syncWeek">同步本周</el-button></div></header>
      <el-alert v-if="week.sync?.latest?.status==='failed'" :title="'最近同步失败，展示上次成功数据：'+week.sync.latest.message" type="warning" :closable="false" />
      <div class="roster-filters"><div class="scope-controls"><span v-if="context.own_only" class="store-label">{{ context.scopes[0]?.label }}</span><template v-else><el-radio-group v-model="scopeType" @change="changeScope"><el-radio-button value="store">门店员工</el-radio-button><el-radio-button value="office">办公室员工</el-radio-button></el-radio-group><StoreRegionSelect v-if="scopeType==='store'" v-model="storeId" :stores="stores" :clearable="false" input-width="240px" @update:model-value="changeScope" /></template></div><div class="week-controls"><el-button aria-label="上一周" :icon="ArrowLeft" @click="moveWeek(-7)" /><el-date-picker v-model="pickedDate" type="date" value-format="YYYY-MM-DD" :clearable="false" style="width:150px" @change="changeWeek" /><el-button aria-label="下一周" :icon="ArrowRight" @click="moveWeek(7)" /><el-button text @click="thisWeek">本周</el-button></div></div>
      <div class="week-caption"><div><b>{{ week.week_start }} — {{ week.dates?.[6] }}</b><span>{{ week.employees?.length || 0 }} 位员工</span></div><div class="legend-list"><span v-for="item in [{value:'work',label:'出勤'},{value:'rest',label:'休息'},{value:'unassigned',label:'未获取 / 待核'}]" :key="item.value" class="legend-item"><i :class="item.value" />{{ item.label }}</span></div></div>
      <div class="roster-scroll" v-loading="loading"><table class="roster-table"><thead><tr><th>员工 <small>点击姓名查看存假</small></th><th v-for="date in week.dates" :key="date" :class="{'today-column':date===context.today}"><span class="weekday">{{ weekdays[new Date(date+'T12:00:00+08:00').getUTCDay()] }}</span><b class="date-number">{{ date.slice(5).replace('-',' / ') }}</b><span v-if="date===context.today" class="today-badge">今天</span></th></tr></thead><tbody><tr v-for="person in week.employees" :key="person.employee_id"><th><button class="employee-name" @click="openBalance(person)"><span class="employee-avatar">{{ person.name.slice(-1) }}</span><span><b>{{ person.name }}</b><small>{{ person.hire_type }}</small></span></button></th><td v-for="day in person.days" :key="day.date" :class="{'today-column':day.date===context.today}"><button :aria-label="`${person.name} ${day.date} ${label(day)}`" :title="day.readonly_reason || '查看计划与实际打卡'" :class="['shift-cell',color(day),{'readonly-cell':!day.can_edit}]" @click="openDay(person,day)"><span class="shift-state"><el-icon v-if="color(day)==='unassigned'"><Plus /></el-icon><b>{{ label(day) }}</b></span><span v-if="day.segments?.length" class="punch-summary plan-summary"><span v-for="(segment,index) in day.segments" :key="index" class="punch-segment">计划 {{ punchRange(segment,day.date) }}</span></span><span v-if="day.pending && day.type!=='unassigned'" class="pending-note">{{ day.reason }}</span><span v-if="day.attendance?.punch_count" class="punch-summary"><span v-for="(segment,index) in day.attendance.segments" :key="index" class="punch-segment">实打 {{ punchRange(segment,day.date) }}</span><span class="punch-total">{{ day.attendance.hours===null?'工时待核':`${day.attendance.incomplete?'已配对':'累计'} ${hoursText(day.attendance.hours)}` }}<em v-if="day.attendance.incomplete">缺卡待核</em></span></span><el-icon v-if="!day.can_edit" class="cell-lock"><Lock /></el-icon></button></td></tr><tr v-if="!week.employees?.length"><td colspan="8" class="empty">请选择门店查看员工考勤</td></tr></tbody></table></div>
      <footer class="roster-footer"><span>计划时间不计作实际工时；缺卡、审批待核和未获取排班不会直接带入工资。</span><span>工资表制作 → 引用钉钉考勤 → 预览并带入草稿</span></footer>
    </section>
    <el-dialog v-model="dayVisible" title="考勤详情" width="min(540px,calc(100vw - 32px))" align-center>
      <template v-if="selectedDay"><div class="dialog-person"><span class="employee-avatar large">{{ selectedPerson.name.slice(-1) }}</span><div><h3>{{ selectedPerson.name }}</h3><p>{{ selectedDay.date }} · {{ label(selectedDay) }}</p></div></div>
        <el-alert v-if="selectedDay.reason" :title="selectedDay.reason" type="info" :closable="false" />
        <h4>钉钉计划班次</h4><p v-for="(segment,index) in selectedDay.segments || []" :key="index">{{ punchRange(segment,selectedDay.date) }}</p><p v-if="!selectedDay.segments?.length">{{ selectedDay.type==='rest'?'休息日':'未获取完整班次' }}</p>
        <h4>实际打卡</h4><p v-for="(segment,index) in selectedDay.attendance?.segments || []" :key="index">{{ punchRange(segment,selectedDay.date) }}</p><p>{{ selectedDay.attendance?.hours==null?'暂无完整打卡工时':hoursText(selectedDay.attendance.hours) }}{{ selectedDay.attendance?.incomplete?' · 缺卡待核':'' }}</p>
      </template><template #footer><el-button @click="dayVisible=false">关闭</el-button></template>
    </el-dialog>
    <el-dialog v-model="balanceVisible" :title="`${balancePerson?.name || ''} · 假期库存`" width="min(850px,96vw)">
      <div v-loading="balanceLoading"><el-alert v-if="balanceError" :title="balanceError" type="error" :closable="false" /><template v-if="account"><div class="balance-summary"><div><small>个人存假可用</small><b>{{ account.balance }} 天</b></div><div><small>本月正常休息剩余</small><b>{{ normalRestRemaining }} 天</b></div><div><small>本月已使用存假</small><b>{{ currentMonth?.used || 0 }} 天</b></div></div><p class="hint">截至 {{ account.as_of }}；{{ account.active_from }} 起启用库存。按已确认考勤核算；钉钉审批类型待核时不自动扣减存假。每笔三个月有效，12 月 31 日结束清空。{{ account.employee.hire_type==='兼职'?'兼职按实际工时计薪，暂不存假。':'' }}</p><h4>存假批次</h4><el-table :data="account.lots" size="small" max-height="200" empty-text="暂无存假"><el-table-column prop="date" label="产生日期" /><el-table-column prop="amount" label="存入天数" /><el-table-column prop="remaining" label="剩余天数" /><el-table-column label="到期日（当日不可用）"><template #default="{row}"><span :class="{'expiring':row.remaining>0 && row.expires_on<=soon}">{{ row.expires_on }}{{ row.remaining>0 && row.expires_on<=soon?' · 即将到期':'' }}</span></template></el-table-column></el-table><h4>库存流水</h4><el-table :data="[...account.events].reverse()" size="small" max-height="220" empty-text="暂无流水"><el-table-column prop="date" label="日期" /><el-table-column label="类型"><template #default="{row}">{{ eventLabels[row.type] }}</template></el-table-column><el-table-column label="天数"><template #default="{row}">{{ row.type==='earn'?'+':'−' }}{{ row.amount }}</template></el-table-column><el-table-column prop="source_date" label="存假来源日期" /></el-table><el-collapse><el-collapse-item title="核算修订记录"><el-table :data="revisions" size="small"><el-table-column prop="version" label="版本" /><el-table-column prop="source" label="原因" /><el-table-column prop="created_at" label="时间" /></el-table></el-collapse-item></el-collapse></template></div>
    </el-dialog>
  </div>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {ArrowLeft,ArrowRight,Plus,Lock,InfoFilled,Check,Clock,Document,CoffeeCup,CircleCheckFilled} from '@element-plus/icons-vue'
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
import {getRosterContext,getRosterWeek,syncRosterWeek,getRosterBalance} from '@/api'
const context=ref({scopes:[],own_only:false}),scope=ref(''),scopeType=ref('store'),storeId=ref(null),pickedDate=ref(''),week=ref({employees:[],dates:[]}),loading=ref(false),saving=ref(false)
const dayVisible=ref(false),selectedPerson=ref(null),selectedDay=ref(null)
const balanceVisible=ref(false),balanceLoading=ref(false),balancePerson=ref(null),account=ref(null),revisions=ref([]),balanceError=ref('')
const weekdays=['周日','周一','周二','周三','周四','周五','周六'],eventLabels={earn:'超额出勤存假',use:'调休扣减',expire:'三个月到期清除',year_clear:'年底清零'}
const stores=computed(()=>context.value.scopes.filter(s=>s.value.startsWith('store:')).map(s=>({id:Number(s.value.split(':')[1]),store_name:s.label})))
const currentMonth=computed(()=>account.value?.months.find(m=>m.period===account.value.as_of.slice(0,7)))
const normalRestRemaining=computed(()=>Math.max(0,(currentMonth.value?.rest_allowance || 0)-(currentMonth.value?.normal_rest_used || 0)))
const add=(date,days)=>{const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
const monday=date=>add(date,-((new Date(date+'T00:00:00Z').getUTCDay()+6)%7))
const soon=computed(()=>account.value?add(account.value.as_of,7):'')
const punchClock=(time,date)=>!time?'未打卡':time.slice(0,10)===date?time.slice(11,16):`${time.slice(5,10).replace('-','/')} ${time.slice(11,16)}`
const punchRange=(segment,date)=>`${punchClock(segment.start_time,date)} — ${punchClock(segment.end_time,segment.start_time?.slice(0,10) || date)}`
const hoursText=hours=>{const total=Math.round(hours*60),h=Math.floor(total/60),m=total%60;return `${h?h+'小时':''}${m?m+'分':''}` || '0分'}
const cellHeight=computed(()=>Math.max(124,52+14*Math.max(4,...(week.value.employees || []).flatMap(person=>person.days.map(day=>(day.segments?.length || 0)+(day.attendance?.segments?.length || 0)+(day.pending && day.type!=='unassigned'?2:0))))))

const color=day=>day.type==='work' && day.actual?.banked>0?'overtime':day.type==='holiday'?'rest':day.type || 'unassigned'
const label=day=>({work:'出勤',rest:'休息',leave:'请假',comp:'调休',overtime:'加班存假',holiday:'休息',unassigned:'未获取 / 待核'})[color(day)] || '未获取 / 待核'
let loadGeneration=0,balanceGeneration=0
async function load(){if(!scope.value || !pickedDate.value)return;const generation=++loadGeneration;loading.value=true;try{const data=await getRosterWeek({scope:scope.value,week_start:monday(pickedDate.value)});if(generation===loadGeneration){week.value=data.week}}catch(error){ElMessage.error(error.message)}finally{if(generation===loadGeneration)loading.value=false}}
function changeScope(){scope.value=scopeType.value==='office'?'office':storeId.value?`store:${storeId.value}`:'';load()}
function changeWeek(){pickedDate.value=monday(pickedDate.value);load()}
function moveWeek(days){pickedDate.value=add(pickedDate.value,days);load()}
function thisWeek(){pickedDate.value=monday(context.value.today);load()}
function openDay(person,day){selectedPerson.value=person;selectedDay.value=day;dayVisible.value=true}
async function syncWeek(){if(!scope.value || !pickedDate.value)return;saving.value=true;const targetScope=scope.value,targetWeek=monday(pickedDate.value);try{const result=await syncRosterWeek({scope:targetScope,week_start:targetWeek});if(scope.value===targetScope && monday(pickedDate.value)===targetWeek)week.value=result.week;ElMessage.success('本周钉钉排班已同步')}catch(error){ElMessage.error(error.message)}finally{saving.value=false}}
async function openBalance(person){balanceVisible.value=true;balancePerson.value=person;account.value=null;balanceError.value='';balanceLoading.value=true;const generation=++balanceGeneration;try{const result=await getRosterBalance(person.employee_id);if(generation===balanceGeneration){account.value=result.account;revisions.value=result.revisions}}catch(error){if(generation===balanceGeneration)balanceError.value=error.message}finally{if(generation===balanceGeneration)balanceLoading.value=false}}
onMounted(async()=>{loading.value=true;try{context.value=await getRosterContext();pickedDate.value=monday(context.value.today);scope.value=context.value.scopes[0]?.value || '';scopeType.value=scope.value==='office'?'office':'store';storeId.value=scope.value.startsWith('store:')?Number(scope.value.split(':')[1]):null;await load()}catch(error){ElMessage.error(error.message)}finally{loading.value=false}})
</script>
